(() => {
'use strict';
const D=window.NBA_COURTSIDE_DATA;
const S=window.NBA_COURTSIDE_SCHEDULE;
const basePlayers=[...D.players];
const teams=[...D.league.teams].sort((a,b)=>a.name.localeCompare(b.name));
const baseGames=[...S.games];
const BASE_CAP={...D.league.cap};
const BASE_DATES={...S.official_dates};
const SAVE_KEY='nbaCourtsideSaveV05';
const LEGACY_TEAM_KEY='nbaCourtsideTeam';
const $=s=>document.querySelector(s);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const initials=n=>(n||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const pretty=s=>(s||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()).replace('Three Pt','3PT');
const money=v=>v==null?'—':v>=1e6?'$'+(v/1e6).toFixed(v>=10e6?1:2)+'M':'$'+Math.round(v/1e3)+'K';
const dateFmt=s=>new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}).toUpperCase();
const shortDate=s=>new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'}).toUpperCase();
const addDays=(s,n)=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const shiftDate=(s,delta)=>{if(!s)return s;const [y,m,d]=s.split('-').map(Number);return `${y+delta}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`};

function initialAssignments(){const a={};for(const p of basePlayers)a[p.id]=p.roster_status==='restricted_free_agent_unsigned'?null:p.team;return a}
function computeOtherCap(){const out={};for(const t of teams){const salary=basePlayers.filter(p=>p.team===t.abbr&&p.roster_status!=='restricted_free_agent_unsigned').reduce((s,p)=>s+(p.contract?.years?.find(y=>y.season_start===2026)?.amount||p.contract?.years?.[0]?.amount||0),0);const holds=basePlayers.filter(p=>p.roster_status==='restricted_free_agent_unsigned'&&(p.rights_team||p.team)===t.abbr).reduce((s,p)=>s+(p.contract?.cap_hold||0),0);out[t.abbr]=(t.cap_hit||salary+holds)-salary-holds}return out}
function newState(){return {version:5,userTeam:'',seasonYear:2026,date:'2026-08-19',phase:'offseason',seasonStarted:false,seasonComplete:false,assignments:initialAssignments(),statusOverrides:{},salaryOverrides:{},deadCap:{},otherCap:computeOtherCap(),results:{},seasonStats:{},transactions:[],news:[],rng:20260819,lastCpuTradeDate:'',postseason:null,awards:null,history:[],playerOverrides:{},retired:[],generatedPlayers:[],draft:null,pickHistory:{},offseasonSummary:null,createdAt:new Date().toISOString()}}
function migrateV4(x){return {...newState(),...x,version:5,seasonYear:x.seasonYear||2026,postseason:x.postseason||null,awards:x.awards||null,history:x.history||[],playerOverrides:x.playerOverrides||{},retired:x.retired||[],generatedPlayers:x.generatedPlayers||[],draft:x.draft||null,pickHistory:x.pickHistory||{},seasonStats:x.seasonStats||{},offseasonSummary:x.offseasonSummary||null}}
function loadState(){try{const x=JSON.parse(localStorage.getItem(SAVE_KEY)||localStorage.getItem('nbaCourtsideSaveV04')||'null');if(x&&x.version===5)return x;if(x&&x.version===4)return migrateV4(x)}catch(e){}return newState()}
let state=loadState();
let players=[...basePlayers,...(state.generatedPlayers||[])];
let byId=new Map(players.map(p=>[p.id,p]));
const teamMap=new Map(teams.map(t=>[t.abbr,t]));
const team=a=>teamMap.get(a);
let games=[];
let DATES={};
let CAP={};
let userTeam=state.userTeam||localStorage.getItem(LEGACY_TEAM_KEY)||'';
let currentView='home';
let leagueTab='standings';
let tradePartner='';
let tradeMine=new Set(),tradeTheirs=new Set();
let tradeOffer=null;

function applyOverrides(){for(const p of players){const o=state.playerOverrides?.[p.id];if(o){if(o.age!=null)p.age=o.age;if(o.ratings)p.ratings=structuredClone(o.ratings);if(o.development_profile)p.development_profile={...(p.development_profile||{}),...o.development_profile}}}}
function refreshSeasonConfig(){const delta=(state.seasonYear||2026)-2026;games=baseGames.map(g=>({...g,id:delta?`${state.seasonYear}-${g.id}`:g.id,date:shiftDate(g.date,delta)}));DATES=Object.fromEntries(Object.entries(BASE_DATES).map(([k,v])=>[k,typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)?shiftDate(v,delta):v]));const growth=Math.pow(1.08,delta);CAP={...BASE_CAP,season:`${state.seasonYear}-${String((state.seasonYear+1)%100).padStart(2,'0')}`,salary_cap:Math.round(BASE_CAP.salary_cap*growth),luxury_tax:Math.round(BASE_CAP.luxury_tax*growth),first_apron:Math.round(BASE_CAP.first_apron*growth),second_apron:Math.round(BASE_CAP.second_apron*growth)}}
function rebuildPlayerIndex(){players=[...basePlayers,...(state.generatedPlayers||[])];byId=new Map(players.map(p=>[p.id,p]));applyOverrides()}
applyOverrides();refreshSeasonConfig();

function persist(){state.userTeam=userTeam;localStorage.setItem(SAVE_KEY,JSON.stringify(state));if(userTeam)localStorage.setItem(LEGACY_TEAM_KEY,userTeam)}
function resetSave(){localStorage.removeItem(SAVE_KEY);localStorage.removeItem('nbaCourtsideSaveV04');localStorage.removeItem(LEGACY_TEAM_KEY);location.reload()}
function currentTeam(p){return Object.prototype.hasOwnProperty.call(state.assignments,p.id)?state.assignments[p.id]:p.team}
function currentStatus(p){return state.statusOverrides[p.id]||p.roster_status}
function salaryBase(p){return p?.contract?.years?.find(y=>y.season_start===state.seasonYear)?.amount ?? p?.contract?.years?.find(y=>y.season_start===2026)?.amount ?? p?.contract?.years?.[0]?.amount ?? p?.contract?.cap_hold ?? 0}
function salaryOf(p){return Object.prototype.hasOwnProperty.call(state.salaryOverrides,p.id)?state.salaryOverrides[p.id]:salaryBase(p)}
function overall(p){return p?.ratings?.overall ?? projectedOverall(p)}
function projectedOverall(p){if(p?.draft_projection?.current_overall)return p.draft_projection.current_overall;const s=salaryOf(p)/1e6;const rookieSignal=clamp((s-4)/12,0,1);return p?.age<=22?Math.round(68+rookieSignal*10):64}
function rating(p,key){if(p?.ratings?.[key]!=null)return p.ratings[key];const o=overall(p);if(key==='offense')return o+(p.positions?.some(x=>['PG','SG'].includes(x))?2:0);if(key==='defense')return o+(p.positions?.includes('C')?2:0);return o}
function role(p){const o=overall(p);if(currentStatus(p)==='draft_prospect')return'Prospect';if(o>=90)return'Superstar';if(o>=85)return'All-Star';if(o>=79)return'Starter';if(o>=73)return'Rotation';if(p.age>=31)return'Veteran';return'Reserve'}
function trend(p){return p?.development_profile?.trend||'stable'}
function pteam(p){return team(currentTeam(p))}
function teamPlayers(a,{activeOnly=false}={}){return players.filter(p=>currentTeam(p)===a&&currentStatus(p)!=='retired'&&currentStatus(p)!=='draft_prospect'&&(!activeOnly||currentStatus(p)==='active'))}
function freeAgents(){return players.filter(p=>currentTeam(p)==null&&currentStatus(p)!=='retired'&&currentStatus(p)!=='draft_prospect')}
function signedCount(a){return teamPlayers(a).length}
function rightsHold(a){return players.filter(p=>currentTeam(p)==null&&p.roster_status==='restricted_free_agent_unsigned'&&(p.rights_team||p.team)===a).reduce((s,p)=>s+(p.contract?.cap_hold||0),0)}
function capHit(a){return teamPlayers(a).reduce((s,p)=>s+salaryOf(p),0)+(state.deadCap[a]||0)+(state.otherCap[a]||0)+rightsHold(a)}
function capStatus(v){return v>CAP.second_apron?'SECOND APRON':v>CAP.first_apron?'FIRST APRON':v>CAP.luxury_tax?'LUXURY TAX':v>CAP.salary_cap?'OVER CAP':'CAP SPACE'}
function setColors(t){if(!t)return;document.documentElement.style.setProperty('--team',t.primary_color);document.documentElement.style.setProperty('--team2',t.secondary_color)}
function img(p,cls=''){if(!p?.headshot_url)return `<div class="${cls} starterFallback">${initials(p?.name||'?')}</div>`;return `<img class="${cls}" src="${p.headshot_url}" alt="${p.name}" onerror="this.style.display='none'">`}
function logo(t,cls=''){if(!t)return '';return `<img class="${cls}" src="${t.logo_url}" alt="${t.abbr}">`}

function record(a){let w=0,l=0,pf=0,pa=0;for(const g of games){const r=state.results[g.id];if(!r)continue;if(g.home===a){pf+=r.home_score;pa+=r.away_score;r.home_score>r.away_score?w++:l++}else if(g.away===a){pf+=r.away_score;pa+=r.home_score;r.away_score>r.home_score?w++:l++}}return {w,l,pf,pa,pct:w+l?w/(w+l):0,diff:w+l?(pf-pa)/(w+l):0}}
function confTeams(c){return teams.filter(t=>t.conference===c).map(t=>({t,r:record(t.abbr)})).sort((a,b)=>b.r.pct-a.r.pct||b.r.diff-a.r.diff||b.r.w-a.r.w)}
function dateState(){if(state.phase==='draft')return'DRAFT';if(state.phase==='free_agency')return'FREE AGENCY';if(state.phase==='playin')return'PLAY-IN';if(state.phase==='playoffs')return'PLAYOFFS';if(state.phase==='champion')return'NBA CHAMPION';if(state.phase==='offseason')return state.seasonStarted?'OFFSEASON':'PRESEASON';if(!state.seasonStarted)return'OFFSEASON';if(state.seasonComplete)return'REGULAR SEASON COMPLETE';if(state.date>DATES.trade_deadline)return'POST-DEADLINE';return'REGULAR SEASON'}
function tradeOpen(){return (state.phase==='offseason'||state.phase==='free_agency'||state.phase==='regular_season')&&!state.seasonComplete&&(!state.seasonStarted||state.date<=DATES.trade_deadline)}
function seasonGamesFor(a){return games.filter(g=>g.home===a||g.away===a)}
function nextGame(a=userTeam){return seasonGamesFor(a).find(g=>g.date>=state.date&&!state.results[g.id])||null}
function lastGame(a=userTeam){return [...seasonGamesFor(a)].reverse().find(g=>state.results[g.id])||null}
function setTop(){const t=team(userTeam);$('#topbar').innerHTML=`<div class="club">${logo(t)}<div><div class="clubName">${t.name}</div><div class="clubMeta">${dateFmt(state.date)} · ${dateState()}</div></div></div><button class="changeBtn" id="changeTeam" aria-label="New save">↻</button>`;$('#changeTeam').onclick=()=>{if(confirm('Start a new NBA Courtside franchise save?'))resetSave()}}

function start(){const counts={};for(const t of teams)counts[t.abbr]=basePlayers.filter(p=>p.team===t.abbr&&p.roster_status!=='restricted_free_agent_unsigned').length;$('#teamGrid').innerHTML=teams.map(t=>`<button class="teamPick" data-pick="${t.abbr}" data-conf="${t.conference}" style="--pick1:${t.primary_color}">${logo(t)}<strong>${t.name}</strong><span>${t.conference.toUpperCase()} · ${counts[t.abbr]} SIGNED</span></button>`).join('');document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>selectTeam(b.dataset.pick));document.querySelectorAll('.confBtn').forEach(b=>b.onclick=()=>{document.querySelectorAll('.confBtn').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.teamPick').forEach(x=>x.classList.toggle('hidden',b.dataset.conf!=='All'&&x.dataset.conf!==b.dataset.conf))});if(userTeam)enterGame()}
function selectTeam(a){userTeam=a;state.userTeam=a;persist();enterGame()}
function enterGame(){const t=team(userTeam);if(!t){userTeam='';return}setColors(t);$('#startScreen').classList.add('hidden');$('#gameApp').classList.remove('hidden');tradePartner=teams.find(x=>x.abbr!==userTeam)?.abbr||'';setTop();renderView()}

function fitScore(p,pos){const o=overall(p);if(p.positions.includes(pos))return o+45;const grp={PG:['SG'],SG:['PG','SF'],SF:['SG','PF'],PF:['SF','C'],C:['PF']}[pos]||[];if(grp.some(x=>p.positions.includes(x)))return o+18;return o-15}
function startingFive(a){const pool=teamPlayers(a,{activeOnly:true}).slice();const used=new Set(),out=[];for(const pos of ['PG','SG','SF','PF','C']){const cand=pool.filter(p=>!used.has(p.id)).sort((x,y)=>fitScore(y,pos)-fitScore(x,pos))[0];if(cand){used.add(cand.id);out.push({pos,p:cand})}}return out}
function topPlayers(a,n=3){return teamPlayers(a,{activeOnly:true}).sort((x,y)=>overall(y)-overall(x)).slice(0,n)}
function starterCard(x){return `<button class="starter" data-player="${x.p.id}"><div class="starterPhoto">${img(x.p)}<span class="starterPos">${x.pos}</span><span class="starterOvr">${overall(x.p)}</span></div><div class="starterName">${x.p.name.split(' ').slice(-1)[0]}</div></button>`}
function hero(){const t=team(userTeam),top=topPlayers(userTeam,3),count=signedCount(userTeam),ch=capHit(userTeam),r=record(userTeam);return `<section class="hero">${logo(t,'heroLogo')}<h1>${t.name.toUpperCase()}</h1><div class="record">${state.seasonStarted&&state.phase==='regular_season'?`${r.w}–${r.l} · ${t.conference.toUpperCase()}`:`${dateState()} · ${CAP.season}`}</div><div class="heroPeople">${top.map(p=>img(p)).join('')}</div><div class="heroStats"><div class="mini"><b>${count}/15</b><span>ROSTER</span></div><div class="mini"><b>${money(ch)}</b><span>CAP HIT</span></div><div class="mini"><b>${capStatus(ch)}</b><span>STATUS</span></div></div></section>`}
function exhibitionLaunch(){return `<a class="exhibitionLaunch" href="exhibition.html"><span>PLAY NOW</span><strong>EXHIBITION MATCH</strong><em>Choose any two NBA teams. Full depth charts, automatic substitutions and real minutes.</em><b>→</b></a>`}
function dateStrip(){return `<div class="dateStrip"><div><span>LEAGUE DATE</span><b>${dateFmt(state.date)}</b></div><div><span>TRADE DEADLINE</span><b>${state.date>DATES.trade_deadline?'CLOSED':shortDate(DATES.trade_deadline)}</b></div></div>`}
function gameCard(g){if(!g)return `<div class="notice">No remaining regular-season games.</div>`;const ht=team(g.home),at=team(g.away),r=state.results[g.id];return `<section class="nextGame"><div class="gameDate">${shortDate(g.date)} · ${r?'FINAL':'NEXT GAME'}</div><div class="matchup"><div class="matchTeam">${logo(at)}<strong>${at.abbr}</strong><span>${record(at.abbr).w}–${record(at.abbr).l}</span></div><div class="scoreVs">${r?`<b>${r.away_score}</b><em>FINAL</em><b>${r.home_score}</b>`:'<b>@</b>'}</div><div class="matchTeam">${logo(ht)}<strong>${ht.abbr}</strong><span>${record(ht.abbr).w}–${record(ht.abbr).l}</span></div></div>${r?.top?`<div class="gameStar">${img(byId.get(r.top.player_id))}<div><span>PLAYER OF THE GAME</span><strong>${byId.get(r.top.player_id)?.name||'Top performer'}</strong><small>${r.top.pts} PTS · ${r.top.reb} REB · ${r.top.ast} AST</small></div></div>`:''}</section>`}

function homeView(){const count=signedCount(userTeam),cut=Math.max(0,count-15),open=Math.max(0,15-count),five=startingFive(userTeam),last=lastGame();
 if(state.phase==='playin'||state.phase==='playoffs'||state.phase==='champion')return postseasonHome();
 if(state.phase==='draft')return draftHome();
 if(state.phase==='free_agency')return freeAgencyHome();
 if(!state.seasonStarted){return `${hero()}${exhibitionLaunch()}${dateStrip()}<div class="sectionHead"><h2>Opening Night</h2><span>${shortDate(DATES.opening_day)}</span></div>${cut?`<div class="notice danger"><strong>${cut} roster cut${cut>1?'s':''} required.</strong> Get to 15 players before opening night.</div>`:open?`<div class="notice warn"><strong>${open} roster spot${open>1?'s':''} open.</strong> You may begin short-handed, but depth matters.</div>`:`<div class="notice good"><strong>Opening-night roster ready.</strong> You have 15 players.</div>`}<button class="primaryAction ${cut?'disabled':''}" id="startSeason" ${cut?'disabled':''}>START ${CAP.season} SEASON</button><div class="sectionHead"><h2>Starting Five</h2><button class="linkBtn" data-jump="roster">FULL ROSTER</button></div><div class="five">${five.map(starterCard).join('')}</div><div class="sectionHead"><h2>Front Office</h2><button class="linkBtn" data-jump="cap">VIEW CAP</button></div><div class="frontGrid"><button data-jump="market"><b>＋</b><span>FREE AGENCY</span></button><button data-jump="trade"><b>⇄</b><span>TRADE CENTER</span></button><button data-jump="league"><b>▦</b><span>LEAGUE</span></button></div>`}
 const ng=nextGame();return `${hero()}${exhibitionLaunch()}${dateStrip()}${last&&last.date===state.date?gameCard(last):''}<div class="sectionHead"><h2>Next Game</h2><span>${ng?shortDate(ng.date):'REGULAR SEASON COMPLETE'}</span></div>${gameCard(ng)}${!state.seasonComplete?`<div class="simGrid"><button id="simDay">SIM NEXT DAY</button><button id="simNextGame">SIM TO NEXT GAME</button><button id="simWeek">SIM 7 DAYS</button></div>`:`${awardsStrip()}<button class="primaryAction" id="beginPostseason">BEGIN ${state.seasonYear+1} POSTSEASON</button>`}<div class="sectionHead"><h2>Starting Five</h2><button class="linkBtn" data-jump="roster">ROSTER</button></div><div class="five">${five.map(starterCard).join('')}</div><div class="sectionHead"><h2>League Pulse</h2><button class="linkBtn" data-jump="league">STANDINGS</button></div>${recentTransactions(3)}`}

function depthRow(p,pos,label){return `<button class="depthRow" data-player="${p.id}" style="color:white;text-align:left"><div class="depthPos">${pos}</div>${img(p,'smallFace')}<div><div class="depthName">${p.name}</div><div class="depthMeta">${label} · AGE ${p.age} · ${p.positions.join('/')}</div></div><div class="depthRight"><b>${overall(p)}</b><span>${money(salaryOf(p))}</span></div></button>`}
function playerCard(p){const tag=currentStatus(p)==='active'?role(p):pretty(currentStatus(p));return `<button class="playerCard" data-player="${p.id}"><div class="pcPhoto">${img(p)}<div class="pcShade"></div><div class="pcOvr">${overall(p)}</div><div class="pcTag">${tag}</div></div><div class="pcInfo"><div class="pcName">${p.name}</div><div class="pcMeta">${p.positions.join(' / ')} · AGE ${p.age} · ${pretty(trend(p))}</div><div class="pcSalary">${money(salaryOf(p))}</div></div></button>`}
function rosterView(){const signed=teamPlayers(userTeam).sort((a,b)=>overall(b)-overall(a)),five=startingFive(userTeam),starters=new Set(five.map(x=>x.p.id));const bench=signed.filter(p=>currentStatus(p)==='active'&&!starters.has(p.id)).sort((a,b)=>overall(b)-overall(a));const unavailable=signed.filter(p=>currentStatus(p)!=='active');return `<div class="sectionHead"><h2>Depth Chart</h2><span>${signed.length}/15 · ${Math.max(0,signed.length-15)} CUTS</span></div>${signed.length>15?`<div class="notice danger"><strong>Roster above 15.</strong> Tap a player and use WAIVE / CUT.</div>`:''}<div class="depthList">${five.map(x=>depthRow(x.p,x.pos,'STARTER')).join('')}</div><div class="groupLabel">Rotation + Reserves</div><div class="depthList">${bench.map((p,i)=>depthRow(p,'B'+(i+1),role(p).toUpperCase())).join('')}</div>${unavailable.length?`<div class="groupLabel">Unavailable / Non-active</div><div class="depthList">${unavailable.map(p=>depthRow(p,'—',pretty(currentStatus(p)).toUpperCase())).join('')}</div>`:''}<div class="sectionHead"><h2>15-Man Roster</h2><button class="linkBtn" data-jump="cap">CAP SHEET</button></div><div class="playerGrid">${signed.map(playerCard).join('')}</div>`}

function capView(){const list=teamPlayers(userTeam).sort((a,b)=>salaryOf(b)-salaryOf(a)),ch=capHit(userTeam),max=CAP.second_apron*1.08,pct=Math.min(100,ch/max*100);const seasons=Array.from({length:6},(_,i)=>`${state.seasonYear+i}-${String((state.seasonYear+i+1)%100).padStart(2,'0')}`);const commitments=seasons.map(s=>({s,v:list.reduce((sum,p)=>sum+(p.contract?.years?.find(y=>y.season===s)?.amount||0),0)}));return `<div class="sectionHead"><h2>Salary Cap</h2><span>${CAP.season}</span></div><section class="capHero"><div class="kicker">TEAM CAP HIT</div><div class="capBig">${money(ch)}</div><div class="capStatus">${capStatus(ch)}</div><div class="capTrack"><div class="capFill" style="width:${pct}%"></div></div><div class="thresholds"><div><b>${money(CAP.salary_cap)}</b>CAP</div><div><b>${money(CAP.luxury_tax)}</b>TAX</div><div><b>${money(CAP.first_apron)}</b>1ST APRON</div><div><b>${money(CAP.second_apron)}</b>2ND APRON</div></div></section><div class="sectionHead"><h2>Future Commitments</h2><span>GUARANTEED / OPTIONS</span></div><div class="future">${commitments.map(x=>`<div class="futureBox"><span>${x.s}</span><b>${money(x.v)}</b></div>`).join('')}</div>${state.deadCap[userTeam]?`<div class="notice warn" style="margin-top:10px"><strong>Waiver hold: ${money(state.deadCap[userTeam])}</strong></div>`:''}<div class="sectionHead"><h2>Contracts</h2><span>${list.length} PLAYERS</span></div><div class="contractList">${list.map(p=>`<button class="contractPlayer" data-player="${p.id}" style="color:white;text-align:left;width:100%">${img(p)}<div><strong>${p.name}</strong><small>${role(p)} · ${p.positions.join('/')}</small></div><div class="contractMoney"><b>${money(salaryOf(p))}</b><span>${p.contract?.expiry||currentStatus(p)}</span></div></button>`).join('')}</div><div class="notice" style="margin-top:10px">The future-cap prototype grows the 2026–27 thresholds by 8% per season until exact future cap figures exist.</div>`}

function marketAsk(p){if(p.roster_status==='restricted_free_agent_unsigned')return p.contract?.qualifying_offer||p.contract?.cap_hold||salaryOf(p);const o=overall(p);return Math.round((o>=90?34:o>=86?26:o>=82?18:o>=78?11:o>=74?7:o>=70?4:2.4)*1e6)}
function marketView(){const fas=freeAgents().sort((a,b)=>overall(b)-overall(a));return `<section class="marketHero"><div class="kicker">PLAYER MARKET</div><h2>FREE<br>AGENCY.</h2><div class="startSub">Every cut, expiry and retirement reshapes the market.</div></section><div class="sectionHead"><h2>Available Players</h2><span>${fas.length} IN MARKET</span></div>${fas.length?fas.map(p=>{const rta=team(p.rights_team||p.team),rfa=p.roster_status==='restricted_free_agent_unsigned';return `<button class="marketCard" data-player="${p.id}" style="width:100%;color:white;text-align:left">${img(p)}<div><div class="marketName">${p.name}</div><div class="marketMeta">${p.positions.join('/')} · AGE ${p.age}${rfa?` · ${rta?.abbr||''} RIGHTS`:' · FREE AGENT'}</div><span class="pill" style="margin-top:6px">${rfa?'RFA':'FA'}</span></div><div class="marketAmount"><b>${money(marketAsk(p))}</b><span>1-YR ASK</span></div></button>`}).join(''):'<div class="notice">No players are currently available.</div>'}<div class="notice warn" style="margin-top:12px"><strong>Prototype contract market:</strong> user free-agent signings are one-year deals. Multi-year negotiations and exceptions are a later cap-engine pass.</div>`}

function assetScore(p){const o=overall(p),growth=trend(p).includes('rising')?6:trend(p).includes('declin')?-5:0,ageAdj=p.age<=24?5:p.age>=34?-4:0,sal=Math.max(1,salaryOf(p)/1e6);return o*1.8+growth+ageAdj-Math.max(0,(sal-25)*.18)}
function selectedPlayers(set){return [...set].map(id=>byId.get(id)).filter(Boolean)}
function salaryMatchLegal(teamAbbr,outSalary,inSalary){const payroll=capHit(teamAbbr);if(payroll<=CAP.salary_cap)return payroll-outSalary+inSalary<=CAP.salary_cap+1000;return inSalary<=outSalary*1.25+250000}
function evaluateTrade(){const a=selectedPlayers(tradeMine),b=selectedPlayers(tradeTheirs);if(!a.length||!b.length)return {ok:false,title:'INCOMPLETE',body:'Add at least one player from each team.'};const sa=a.reduce((s,p)=>s+salaryOf(p),0),sb=b.reduce((s,p)=>s+salaryOf(p),0);const userCount=signedCount(userTeam)-a.length+b.length,cpuCount=signedCount(tradePartner)-b.length+a.length;if(userCount>15||cpuCount>15)return {ok:false,title:'ROSTER ILLEGAL',body:'This deal would leave a team above 15 players.'};if(!salaryMatchLegal(userTeam,sa,sb)||!salaryMatchLegal(tradePartner,sb,sa))return {ok:false,title:'SALARY MATCH FAIL',body:'The simplified salary-matching test rejects this trade.'};const give=a.reduce((s,p)=>s+assetScore(p),0),get=b.reduce((s,p)=>s+assetScore(p),0),best=Math.max(...b.map(overall));const premium=best>=90?1.28:best>=85?1.14:1.02;const threshold=get*premium;if(give>=threshold)return {ok:true,title:'TRADE ACCEPTED',body:'The CPU accepts the basketball value and salary framework.'};if(give>=threshold*.92)return {ok:false,title:'THEY’RE LISTENING',body:'The value is close, but the CPU wants a stronger package.'};return {ok:false,title:'DECLINED',body:'The CPU values its outgoing package more highly.'}}
function tradeSummary(){const a=selectedPlayers(tradeMine),b=selectedPlayers(tradeTheirs),sa=a.reduce((s,p)=>s+salaryOf(p),0),sb=b.reduce((s,p)=>s+salaryOf(p),0),va=a.reduce((s,p)=>s+assetScore(p),0),vb=b.reduce((s,p)=>s+assetScore(p),0);return `<div class="tradeSummary"><div class="tradeSum"><span>YOU SEND</span><b>${a.length} · ${money(sa)}</b></div><div class="tradeSum"><span>YOU RECEIVE</span><b>${b.length} · ${money(sb)}</b></div><div class="tradeSum"><span>YOUR VALUE</span><b>${Math.round(va)}</b></div><div class="tradeSum"><span>CPU VALUE</span><b>${Math.round(vb)}</b></div></div>`}
function offerSide(t,list,set,side){return `<section class="offerSide"><div class="offerHead">${logo(t)}<strong>${t.name}</strong><span class="pill" style="margin-left:auto">SELECT UP TO 3</span></div><div class="assetGrid">${list.slice(0,15).map(p=>`<button class="asset ${set.has(p.id)?'selected':''}" data-asset="${p.id}" data-side="${side}">${img(p)}<b>${p.name}</b></button>`).join('')}</div></section>`}
function tradeView(){if(!tradePartner||tradePartner===userTeam)tradePartner=teams.find(t=>t.abbr!==userTeam).abbr;const ut=team(userTeam),pt=team(tradePartner);const mine=teamPlayers(userTeam,{activeOnly:true}).sort((a,b)=>overall(b)-overall(a));const theirs=teamPlayers(tradePartner,{activeOnly:true}).sort((a,b)=>overall(b)-overall(a));if(!tradeOpen())return `<div class="sectionHead"><h2>Trade Center</h2><span>LOCKED</span></div><div class="deadlineLock"><b>TRADES LOCKED</b><span>Trades are unavailable during the postseason and after the in-season deadline.</span></div>`;return `<div class="sectionHead"><h2>Trade Center</h2><span>${state.seasonStarted?`${shortDate(DATES.trade_deadline)} DEADLINE`:'OFFSEASON'}</span></div><div class="partnerStrip">${teams.filter(t=>t.abbr!==userTeam).map(t=>`<button class="partner ${t.abbr===tradePartner?'active':''}" data-partner="${t.abbr}">${logo(t)}</button>`).join('')}</div>${offerSide(ut,mine,tradeMine,'mine')}${offerSide(pt,theirs,tradeTheirs,'theirs')}<div id="tradeCalc">${tradeSummary()}</div><button class="propose" id="proposeTrade">PROPOSE TRADE</button><div class="response hidden" id="tradeResponse"></div>`}
function proposeTrade(){tradeOffer=evaluateTrade();const r=$('#tradeResponse');r.classList.remove('hidden');r.innerHTML=`<strong>${tradeOffer.title}</strong><br>${tradeOffer.body}${tradeOffer.ok?'<button class="completeTrade" id="completeTrade">COMPLETE TRADE</button>':''}`;if(tradeOffer.ok)$('#completeTrade').onclick=completeTrade}
function completeTrade(){if(!tradeOffer?.ok)return;const mine=selectedPlayers(tradeMine),theirs=selectedPlayers(tradeTheirs),pt=tradePartner;for(const p of mine)state.assignments[p.id]=pt;for(const p of theirs)state.assignments[p.id]=userTeam;addTransaction('TRADE',`${team(userTeam).abbr} acquired ${theirs.map(p=>p.name).join(', ')} from ${team(pt).abbr} for ${mine.map(p=>p.name).join(', ')}.`);tradeMine.clear();tradeTheirs.clear();tradeOffer=null;persist();renderView();toast('TRADE COMPLETE')}

function leagueView(){const tabs=`<div class="leagueTabs"><button data-ltab="standings" class="${leagueTab==='standings'?'active':''}">STANDINGS</button><button data-ltab="schedule" class="${leagueTab==='schedule'?'active':''}">SCHEDULE</button><button data-ltab="transactions" class="${leagueTab==='transactions'?'active':''}">MOVES</button><button data-ltab="history" class="${leagueTab==='history'?'active':''}">HISTORY</button></div>`;let body='';if(leagueTab==='standings')body=standingsView();if(leagueTab==='schedule')body=scheduleView();if(leagueTab==='transactions')body=transactionsView();if(leagueTab==='history')body=historyView();return `<div class="sectionHead"><h2>The League</h2><span>${dateFmt(state.date)}</span></div>${tabs}${body}`}
function standingsTable(conf){const rows=confTeams(conf);return `<div class="standings"><div class="standHead"><span>${conf.toUpperCase()}</span><span>W</span><span>L</span><span>PCT</span><span>DIFF</span></div>${rows.map((x,i)=>`<div class="standRow ${x.t.abbr===userTeam?'you':''}"><div><b>${i+1}</b>${logo(x.t)}<strong>${x.t.abbr}</strong></div><span>${x.r.w}</span><span>${x.r.l}</span><span>${x.r.pct.toFixed(3).replace('0.','.')}</span><span>${x.r.diff>=0?'+':''}${x.r.diff.toFixed(1)}</span></div>`).join('')}</div>`}
function standingsView(){return `${standingsTable('East')}<div style="height:10px"></div>${standingsTable('West')}`}
function scheduleView(){const mine=seasonGamesFor(userTeam),idx=Math.max(0,mine.findIndex(g=>g.date>=state.date&&!state.results[g.id]));const start=Math.max(0,idx-3),slice=mine.slice(start,start+12);return `<div class="scheduleList">${slice.map(g=>{const opp=g.home===userTeam?team(g.away):team(g.home),home=g.home===userTeam,r=state.results[g.id];return `<div class="scheduleRow ${g.date===state.date?'today':''}"><span>${shortDate(g.date)}</span>${logo(opp)}<div><strong>${home?'vs':'@'} ${opp.name}</strong><small>${r?`${r.away_score}–${r.home_score} FINAL`:'SCHEDULED'}</small></div><b>${r?(g.home===userTeam?(r.home_score>r.away_score?'W':'L'):(r.away_score>r.home_score?'W':'L')):'—'}</b></div>`}).join('')}</div>`}
function recentTransactions(n=99){const tx=[...state.transactions].reverse().slice(0,n);return tx.length?`<div class="txList">${tx.map(x=>`<div class="txRow"><span>${shortDate(x.date)}</span><b>${x.type}</b><p>${x.text}</p></div>`).join('')}</div>`:`<div class="notice">No transactions have occurred in this save yet.</div>`}
function transactionsView(){return recentTransactions()}

function historyView(){const h=[...state.history].reverse();if(!h.length)return `<div class="notice">League history begins after the first completed NBA Finals.</div>`;return `<div class="historyList">${h.map(x=>{const c=team(x.champion),a=x.awards||{};return `<div class="historyCard"><div class="historySeason">${x.season}–${String((x.season+1)%100).padStart(2,'0')}</div><div class="historyChamp">${logo(c)}<div><span>NBA CHAMPION</span><strong>${c?.name||x.champion}</strong></div></div><div class="historyAwards"><span>MVP <b>${byId.get(a.mvp)?.name||'—'}</b></span><span>DPOY <b>${byId.get(a.dpoy)?.name||'—'}</b></span><span>ROY <b>${byId.get(a.roy)?.name||'—'}</b></span></div></div>`}).join('')}</div>`}

function rng(){state.rng=(1664525*(state.rng>>>0)+1013904223)>>>0;return state.rng/4294967296}
function normal(){let u=0,v=0;while(!u)u=rng();while(!v)v=rng();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function hash01(s){let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return((h>>>0)%10000)/10000}
function ensureProjectionRating(p){if(p.ratings||p.age>23)return;const o=projectedOverall(p),lean=hash01(p.name);p.ratings={overall:o,skill_overall:o,impact:o,offense:clamp(Math.round(o+(lean-.5)*4),50,95),defense:clamp(Math.round(o+(.5-lean)*4),50,95),finishing:o,three_pt:clamp(o+(p.positions.includes('C')?-7:1),45,92),free_throw:clamp(o+2,50,94),shot_creation:o,playmaking:clamp(o+(p.positions.includes('PG')?5:-1),50,95),ball_security:o,offensive_rebounding:clamp(o+(p.positions.includes('C')?5:-3),45,95),defensive_rebounding:clamp(o+(p.positions.includes('C')?6:-1),45,95),stamina:clamp(o+5,55,96),perimeter_defense:clamp(o+(p.positions.includes('C')?-4:1),45,95),interior_defense:clamp(o+(p.positions.includes('C')?6:-2),45,95)};state.playerOverrides[p.id]={...(state.playerOverrides[p.id]||{}),age:p.age,ratings:structuredClone(p.ratings)};p.rating_source='2026_rookie_projection'}
function ensureAllProjectionRatings(){for(const p of teamPlayers(userTeam))ensureProjectionRating(p);for(const t of teams)for(const p of teamPlayers(t.abbr))ensureProjectionRating(p)}
function rotation(a){return teamPlayers(a,{activeOnly:true}).sort((x,y)=>overall(y)-overall(x)).slice(0,10)}
function metrics(a){const ps=rotation(a),weights=[1,1,.96,.92,.88,.65,.55,.45,.35,.25].slice(0,ps.length),ws=weights.reduce((a,b)=>a+b,0)||1;let off=0,def=0,ov=0;ps.forEach((p,i)=>{off+=rating(p,'offense')*weights[i];def+=rating(p,'defense')*weights[i];ov+=overall(p)*weights[i]});const shortage=Math.max(0,8-ps.length)*2.5;return {off:off/ws-shortage,def:def/ws-shortage,ov:ov/ws-shortage,players:ps}}
function allocateMinutes(ps){const raw=[35,34,33,31,29,24,20,16,11,7].slice(0,ps.length);const sum=raw.reduce((a,b)=>a+b,0)||1;return raw.map(x=>x*240/sum)}
function statBase(p,key,fallback){const s=p.simulation_profile,old=p.stats_2025_26;if(s&&s[key]!=null)return s[key];const map={pts_per36:'pts',reb_per36:'reb',ast_per36:'ast',stl_per36:'stl',blk_per36:'blk',tov_per36:'tov'};if(old&&map[key])return (old[map[key]]||0)/(old.mpg||30)*36;return fallback}
function generateLines(a,teamScore){const ps=rotation(a),mins=allocateMinutes(ps),lines=[];let projectedPts=0;for(let i=0;i<ps.length;i++){const p=ps[i],m=mins[i];const base=statBase(p,'pts_per36',Math.max(7,(overall(p)-56)*.8));projectedPts+=base*m/36}const scale=teamScore/Math.max(70,projectedPts);for(let i=0;i<ps.length;i++){const p=ps[i],m=mins[i];const pts=clamp(Math.round(statBase(p,'pts_per36',Math.max(7,(overall(p)-56)*.8))*m/36*scale+normal()*2.8),0,55);const reb=clamp(Math.round(statBase(p,'reb_per36',p.positions.includes('C')?9:4.5)*m/36+normal()*1.3),0,24);const ast=clamp(Math.round(statBase(p,'ast_per36',p.positions.includes('PG')?7:3)*m/36+normal()*1.2),0,18);const stl=clamp(Math.round(statBase(p,'stl_per36',1.1)*m/36+normal()*.45),0,7);const blk=clamp(Math.round(statBase(p,'blk_per36',p.positions.includes('C')?1.3:.5)*m/36+normal()*.4),0,8);const tov=clamp(Math.round(statBase(p,'tov_per36',2)*m/36+normal()*.7),0,9);lines.push({player_id:p.id,min:Math.round(m),pts,reb,ast,stl,blk,tov})}return lines}
function addSeasonLine(line){const x=state.seasonStats[line.player_id]||(state.seasonStats[line.player_id]={gp:0,min:0,pts:0,reb:0,ast:0,stl:0,blk:0,tov:0});x.gp++;for(const k of ['min','pts','reb','ast','stl','blk','tov'])x[k]+=line[k]}
function pickTopLine(lines){return [...lines].sort((a,b)=>(b.pts+b.reb*.7+b.ast*.8+b.stl*2+b.blk*2)-(a.pts+a.reb*.7+a.ast*.8+a.stl*2+a.blk*2))[0]}
function simulateStandaloneGame(home,away){const hm=metrics(home),am=metrics(away);const hExp=113.5+(hm.off-75)*.48-(am.def-75)*.37+1.7;const aExp=113.5+(am.off-75)*.48-(hm.def-75)*.37;let hs=clamp(Math.round(hExp+normal()*9),82,149),as=clamp(Math.round(aExp+normal()*9),82,149);if(hs===as){hs+=clamp(Math.round(9+normal()*3),4,18);as+=clamp(Math.round(9+normal()*3),4,18);if(hs===as)hs++}return {home_score:hs,away_score:as,winner:hs>as?home:away}}
function simulateGame(g){if(state.results[g.id])return;const score=simulateStandaloneGame(g.home,g.away),hl=generateLines(g.home,score.home_score),al=generateLines(g.away,score.away_score);for(const l of [...hl,...al])addSeasonLine(l);const top=pickTopLine(score.winner===g.home?hl:al);state.results[g.id]={...score,top}}
function simDate(d){for(const g of games.filter(x=>x.date===d))simulateGame(g);maybeCpuTrade(d)}
function datesBetween(a,b){const out=[];let d=a;while(d<=b){out.push(d);d=addDays(d,1)}return out}
function advanceTo(target){target=target>DATES.regular_season_end?DATES.regular_season_end:target;for(const d of datesBetween(state.date,target))simDate(d);state.date=target;if(target>=DATES.regular_season_end&&games.every(g=>state.results[g.id])){state.seasonComplete=true;state.phase='regular_season';generateAwards()}persist();setTop();renderView()}
function simNextDay(){let d=state.date;do{d=addDays(d,1)}while(d<=DATES.regular_season_end&&!games.some(g=>g.date===d));advanceTo(d<=DATES.regular_season_end?d:DATES.regular_season_end)}
function simToNextGame(){const ng=nextGame();if(!ng){advanceTo(DATES.regular_season_end);return}advanceTo(ng.date)}
function simWeek(){advanceTo(addDays(state.date,7))}
function startSeason(){if(signedCount(userTeam)>15)return;ensureAllProjectionRatings();autoTrimCpu();autoFillCpu();state.seasonStarted=true;state.seasonComplete=false;state.phase='regular_season';state.date=DATES.opening_day;state.results={};state.seasonStats={};state.postseason=null;state.awards=null;persist();setTop();renderView();toast(`${CAP.season} SEASON STARTED`)}

function statAvg(id,k){const x=state.seasonStats[id];return x&&x.gp?x[k]/x.gp:0}
function awardScore(p){const r=record(currentTeam(p)||p.team),pts=statAvg(p.id,'pts'),reb=statAvg(p.id,'reb'),ast=statAvg(p.id,'ast'),stl=statAvg(p.id,'stl'),blk=statAvg(p.id,'blk');return pts*1.15+reb*.42+ast*.65+stl*1.6+blk*1.6+overall(p)*.23+r.w*.15}
function defenseAwardScore(p){const r=record(currentTeam(p)||p.team);return rating(p,'defense')*.65+statAvg(p.id,'reb')*.5+statAvg(p.id,'stl')*3+statAvg(p.id,'blk')*3+r.w*.1}
function generateAwards(){if(state.awards)return;const eligible=players.filter(p=>currentTeam(p)&&state.seasonStats[p.id]?.gp>=30&&currentStatus(p)==='active');const mvp=[...eligible].sort((a,b)=>awardScore(b)-awardScore(a))[0];const dpoy=[...eligible].sort((a,b)=>defenseAwardScore(b)-defenseAwardScore(a))[0];const rookies=eligible.filter(p=>p.career_status==='rookie_2026_projection_pending'||p.rating_source==='2026_rookie_projection'||p.draft_projection?.rookieSeason===state.seasonYear);const roy=[...rookies].sort((a,b)=>awardScore(b)-awardScore(a))[0];const starters=new Set(teams.flatMap(t=>startingFive(t.abbr).map(x=>x.p.id)));const bench=eligible.filter(p=>!starters.has(p.id));const smoy=[...bench].sort((a,b)=>awardScore(b)-awardScore(a))[0];const mip=[...eligible].filter(p=>p.age<=27).sort((a,b)=>((trend(b).includes('rising')?4:0)+awardScore(b))-((trend(a).includes('rising')?4:0)+awardScore(a)))[0];state.awards={mvp:mvp?.id||null,dpoy:dpoy?.id||null,roy:roy?.id||null,smoy:smoy?.id||null,mip:mip?.id||null,generatedFor:state.seasonYear}}
function awardTile(label,id){const p=byId.get(id);if(!p)return'';return `<div class="awardTile">${img(p)}<span>${label}</span><strong>${p.name}</strong><small>${currentTeam(p)||''} · ${overall(p)} OVR</small></div>`}
function awardsStrip(){if(!state.awards)return'';return `<div class="sectionHead"><h2>Season Awards</h2><span>${state.seasonYear+1}</span></div><div class="awardScroll">${awardTile('MVP',state.awards.mvp)}${awardTile('DPOY',state.awards.dpoy)}${awardTile('ROY',state.awards.roy)}${awardTile('6TH MAN',state.awards.smoy)}${awardTile('MOST IMPROVED',state.awards.mip)}</div>`}

function beginPostseason(){if(!state.seasonComplete)return;generateAwards();const east=confTeams('East'),west=confTeams('West');state.postseason={stage:'playin',east:{standings:east.map(x=>x.t.abbr),seed7:null,seed8:null,playin:[]},west:{standings:west.map(x=>x.t.abbr),seed7:null,seed8:null,playin:[]},round:0,rounds:[],champion:null,finals:null};state.phase='playin';state.date=shiftDate('2027-04-13',state.seasonYear-2026);persist();renderView();setTop()}
function simPlayInConf(key){const c=state.postseason[key],s=c.standings;const a=simulateStandaloneGame(s[6],s[7]);const winner78=a.winner,loser78=winner78===s[6]?s[7]:s[6];const b=simulateStandaloneGame(s[8],s[9]);const winner910=b.winner,loser910=winner910===s[8]?s[9]:s[8];const f=simulateStandaloneGame(loser78,winner910);c.seed7=winner78;c.seed8=f.winner;c.loser78=loser78;c.loser910=loser910;c.playin=[{home:s[6],away:s[7],...a,label:'7 vs 8'},{home:s[8],away:s[9],...b,label:'9 vs 10'},{home:loser78,away:winner910,...f,label:'8-SEED GAME'}]}
function simulatePlayIn(){simPlayInConf('east');simPlayInConf('west');state.postseason.stage='playoffs';state.postseason.round=1;state.phase='playoffs';buildRoundOne();state.date=shiftDate('2027-04-18',state.seasonYear-2026);persist();renderView();setTop();toast('PLAY-IN COMPLETE')}
function buildRoundOne(){const make=(key)=>{const c=state.postseason[key],s=c.standings;return [[s[0],c.seed8],[s[1],c.seed7],[s[2],s[5]],[s[3],s[4]]].map((x,i)=>({conference:key,round:1,slot:i,a:x[0],b:x[1],winner:null,result:null}))};state.postseason.rounds=[...make('east'),...make('west')]}
function simulateSeries(a,b){let aw=0,bw=0,g=0;const gamesOut=[];while(aw<4&&bw<4&&g<7){const home=(g===0||g===1||g===4||g===6)?a:b,away=home===a?b:a,r=simulateStandaloneGame(home,away);r.winner===a?aw++:bw++;gamesOut.push({game:g+1,home,away,...r});g++}return {a,b,aWins:aw,bWins:bw,winner:aw>bw?a:b,games:gamesOut}}
function currentRoundSeries(){return state.postseason.rounds.filter(x=>x.round===state.postseason.round)}
function simulatePlayoffRound(){const r=state.postseason.round,series=currentRoundSeries();for(const s of series){if(!s.winner){s.result=simulateSeries(s.a,s.b);s.winner=s.result.winner}}if(r===1){for(const key of ['east','west']){const w=series.filter(s=>s.conference===key).map(s=>s.winner);state.postseason.rounds.push({conference:key,round:2,slot:0,a:w[0],b:w[3],winner:null,result:null},{conference:key,round:2,slot:1,a:w[1],b:w[2],winner:null,result:null})}state.postseason.round=2}
 else if(r===2){for(const key of ['east','west']){const w=series.filter(s=>s.conference===key).map(s=>s.winner);state.postseason.rounds.push({conference:key,round:3,slot:0,a:w[0],b:w[1],winner:null,result:null})}state.postseason.round=3}
 else if(r===3){const ew=series.find(s=>s.conference==='east').winner,ww=series.find(s=>s.conference==='west').winner,er=record(ew),wr=record(ww),a=(er.pct>wr.pct||(er.pct===wr.pct&&er.diff>=wr.diff))?ew:ww,b=a===ew?ww:ew;state.postseason.rounds.push({conference:'finals',round:4,slot:0,a,b,winner:null,result:null});state.postseason.round=4}
 else if(r===4){const f=series[0];state.postseason.champion=f.winner;state.postseason.finals=f.result;state.postseason.stage='champion';state.phase='champion';addTransaction('CHAMPION',`${team(f.winner).name} won the ${state.seasonYear+1} NBA Championship.`);toast(`${team(f.winner).abbr} ARE CHAMPIONS`)}persist();renderView();setTop()}
function seriesCard(s){const ta=team(s.a),tb=team(s.b),res=s.result;return `<div class="seriesCard"><div>${logo(ta)}<strong>${ta.abbr}</strong><span>${res?res.aWins:'—'}</span></div><em>${res?'FINAL':'VS'}</em><div>${logo(tb)}<strong>${tb.abbr}</strong><span>${res?res.bWins:'—'}</span></div>${s.winner?`<b>${team(s.winner).abbr} ADVANCES</b>`:''}</div>`}
function playinCard(c,key){return `<div class="postConf"><h3>${key.toUpperCase()}</h3>${c.playin.length?c.playin.map(g=>`<div class="playinGame"><span>${g.label}</span>${logo(team(g.away))}<b>${g.away_score}</b><em>—</em><b>${g.home_score}</b>${logo(team(g.home))}</div>`).join(''):`<div class="notice">Seeds 7–10 are set. Simulate the Play-In to determine the final two playoff spots.</div>`}</div>`}
function postseasonHome(){const p=state.postseason;if(!p)return'';if(state.phase==='playin')return `${hero()}${awardsStrip()}<div class="postHero"><span>${state.seasonYear+1} POSTSEASON</span><h2>PLAY-IN<br>TOURNAMENT.</h2></div>${playinCard(p.east,'east')}${playinCard(p.west,'west')}<button class="primaryAction" id="simPlayIn">SIMULATE PLAY-IN</button>`;if(state.phase==='playoffs'){const labels={1:'FIRST ROUND',2:'CONFERENCE SEMIFINALS',3:'CONFERENCE FINALS',4:'NBA FINALS'},series=currentRoundSeries();return `${hero()}<div class="postHero"><span>NBA PLAYOFFS</span><h2>${labels[p.round]}</h2></div><div class="seriesGrid">${series.map(seriesCard).join('')}</div><button class="primaryAction" id="simRound">SIMULATE ${labels[p.round]}</button>`}const champ=team(p.champion);return `${hero()}<div class="championHero">${logo(champ,'champLogo')}<span>${state.seasonYear+1} NBA CHAMPIONS</span><h2>${champ.name.toUpperCase()}</h2><div class="champFaces">${topPlayers(champ.abbr,3).map(x=>img(x)).join('')}</div></div>${awardsStrip()}<button class="primaryAction" id="beginOffseason">BEGIN ${state.seasonYear+1} OFFSEASON</button>`}

function retirementChance(p){if(p.age<=35)return 0;if(p.age===36)return .02;if(p.age===37)return .05;if(p.age===38)return .12;if(p.age===39)return .25;if(p.age===40)return .42;if(p.age===41)return .62;if(p.age===42)return .82;return 1}
function developmentDelta(p){const a=p.age,base=p.development_profile?.baseline_next_year_overall_delta||0;let d=0;if(a<=21)d=2.2;else if(a<=23)d=1.6;else if(a<=25)d=1.0;else if(a<=28)d=.35;else if(a<=30)d=0;else if(a<=32)d=-.4;else if(a<=34)d=-.9;else if(a<=36)d=-1.5;else if(a<=38)d=-2.3;else d=-3.5;d=(d+base*.45)+normal()*.55;if(p.draft_projection?.potential)d=Math.min(d,p.draft_projection.potential-overall(p));return clamp(d,-5,3.5)}
function applyDevelopment(p){const old=overall(p);p.age+=1;const d=developmentDelta(p),newO=clamp(Math.round(old+d),55,99);if(p.ratings){const factor=newO-old;for(const k of Object.keys(p.ratings)){if(typeof p.ratings[k]==='number')p.ratings[k]=clamp(Math.round(p.ratings[k]+factor+(k==='three_pt'||k==='playmaking'?Math.max(0,p.age-30)*.05:0)),40,99)}p.ratings.overall=newO}else ensureProjectionRating(p);let tr='stable';if(d>=1.5)tr='rising_fast';else if(d>.4)tr='rising';else if(d<=-2)tr='declining_fast';else if(d<-.4)tr='declining';p.development_profile={...(p.development_profile||{}),trend:tr,baseline_next_year_overall_delta:+d.toFixed(1)};state.playerOverrides[p.id]={age:p.age,ratings:structuredClone(p.ratings),development_profile:structuredClone(p.development_profile)};return {old,new:newO,delta:newO-old}}
function processContractsForNextSeason(oldYear){const next=oldYear+1,released=[];state.salaryOverrides={};for(const p of players){if(currentStatus(p)==='retired'||currentStatus(p)==='draft_prospect')continue;const tm=currentTeam(p);if(!tm)continue;const yr=p.contract?.years?.find(y=>y.season_start===next);if(!yr){state.assignments[p.id]=null;state.statusOverrides[p.id]='free_agent';released.push(p.name);continue}if(yr.option==='player_option'){if(marketAsk(p)>yr.amount*1.18&&p.age<35){state.assignments[p.id]=null;state.statusOverrides[p.id]='free_agent';released.push(p.name+' (opted out)')}}else if(yr.option==='team_option'){const keep=overall(p)>=69||yr.amount<marketAsk(p)*1.15;if(!keep){state.assignments[p.id]=null;state.statusOverrides[p.id]='free_agent';released.push(p.name+' (option declined)')}}}return released}
function beginOffseason(){const oldYear=state.seasonYear,champ=state.postseason?.champion;const records=Object.fromEntries(teams.map(t=>[t.abbr,record(t.abbr)]));state.history.push({season:oldYear,champion:champ,awards:structuredClone(state.awards),records});const lottery=buildDraftOrder(records);const retirements=[],development=[];for(const p of players){if(currentStatus(p)==='retired'||currentStatus(p)==='draft_prospect')continue;const dev=applyDevelopment(p);development.push({id:p.id,...dev});let chance=retirementChance(p);if(overall(p)<68&&p.age>=35)chance+=.12;if(rng()<chance){const tm=currentTeam(p);state.assignments[p.id]=null;state.statusOverrides[p.id]='retired';retirements.push({id:p.id,name:p.name,team:tm,age:p.age});state.retired.push(p.id);addTransaction('RETIRED',`${p.name} retired at age ${p.age}.`,`${oldYear+1}-06-01`)}}const released=processContractsForNextSeason(oldYear);state.deadCap={};state.otherCap=Object.fromEntries(teams.map(t=>[t.abbr,0]));state.seasonYear=oldYear+1;state.seasonStarted=false;state.seasonComplete=false;state.results={};state.seasonStats={};state.postseason=null;state.awards=null;state.phase='draft';state.date=`${state.seasonYear}-06-20`;state.offseasonSummary={retirements,development:development.sort((a,b)=>b.delta-a.delta),released};state.draft=lottery;generateDraftClass();refreshSeasonConfig();persist();renderView();setTop();toast('OFFSEASON BEGINS')}

function weightedDraw(items,weights){const total=weights.reduce((a,b)=>a+b,0);let r=rng()*total;for(let i=0;i<items.length;i++){r-=weights[i];if(r<=0)return i}return items.length-1}
function buildDraftOrder(records){const east=confTeams('East').map(x=>x.t.abbr),west=confTeams('West').map(x=>x.t.abbr);const nonPlayin=[...east.slice(10),...west.slice(10)],seed9s=[east[8],east[9],west[8],west[9]];const loser78=[state.postseason?.east?.loser78,state.postseason?.west?.loser78].filter(Boolean);const overallWorst=[...teams].sort((a,b)=>records[a.abbr].pct-records[b.abbr].pct||records[a.abbr].diff-records[b.abbr].diff).slice(0,3).map(t=>t.abbr);const entrants=[];for(const a of nonPlayin)entrants.push({team:a,balls:overallWorst.includes(a)?2:3,relegated:overallWorst.includes(a)});for(const a of seed9s)if(!entrants.find(x=>x.team===a))entrants.push({team:a,balls:2,relegated:false});for(const a of loser78)if(!entrants.find(x=>x.team===a))entrants.push({team:a,balls:1,relegated:false});while(entrants.length<16){const pool=[...east,...west].filter(a=>!entrants.find(x=>x.team===a)).sort((a,b)=>records[a].pct-records[b].pct);entrants.push({team:pool.shift(),balls:1,relegated:false})}const remaining=[...entrants],lottery=[],draftYear=oldDraftYear(),prev=state.pickHistory[draftYear-1]||[],prev2=state.pickHistory[draftYear-2]||[];for(let pick=1;pick<=16;pick++){let allowed=remaining.map((x,i)=>({x,i}));if(pick===1&&prev[0])allowed=allowed.filter(z=>z.x.team!==prev[0]);if(pick<=5&&prev.length&&prev2.length)allowed=allowed.filter(z=>!(prev.slice(0,5).includes(z.x.team)&&prev2.slice(0,5).includes(z.x.team)));const relegated=remaining.filter(x=>x.relegated),slotsTo12=13-pick;if(relegated.length&&slotsTo12<=relegated.length){const forced=allowed.filter(z=>z.x.relegated);if(forced.length)allowed=forced}if(!allowed.length)allowed=remaining.map((x,i)=>({x,i}));const local=weightedDraw(allowed,allowed.map(z=>z.x.balls));const idx=allowed[local].i;lottery.push(remaining[idx].team);remaining.splice(idx,1)}const nonLottery=teams.map(t=>t.abbr).filter(a=>!lottery.includes(a)).sort((a,b)=>records[a].pct-records[b].pct||records[a].diff-records[b].diff);const first=[...lottery,...nonLottery];const second=teams.map(t=>t.abbr).sort((a,b)=>records[a].pct-records[b].pct||records[a].diff-records[b].diff);return {year:oldDraftYear(),stage:'ready',order:[...first,...second],pickIndex:0,selections:[],lotteryEntrants:entrants,lotteryOrder:lottery,records,generated:false}}
function oldDraftYear(){return state.seasonYear+1}
const firstNames=['Jalen','Malik','Cameron','Isaiah','Noah','Elijah','Jordan','Micah','Tyrese','Jaylen','Andre','Marcus','Darius','Kylan','Tre','Miles','Zion','Devin','Caleb','Nico','Luka','Kai','Xavier','Terrence','Julian','Amari','Jace','Kobe','Mason','Eli'];
const lastNames=['Holloway','Mercer','Banks','Whitmore','Ellis','Vaughn','Cross','Davenport','Bishop','Hayes','Monroe','Foster','Lawson','Griffin','Sampson','Pierce','Maddox','Carver','Warren','Sloan','Jefferson','McKnight','Brooks','Parker','Mills','King','Harding','Stone','Fields','Reed'];
function prospectName(i){return `${firstNames[(i*7+Math.floor(rng()*firstNames.length))%firstNames.length]} ${lastNames[(i*11+Math.floor(rng()*lastNames.length))%lastNames.length]}`}
function rookieSalaryForPick(pick){const first=15.5e6*Math.pow(.965,pick-1);return Math.round(clamp(first,1.3e6,15.5e6)/1000)*1000}
function makeProspect(i){const pickBand=i+1,age=18+Math.floor(rng()*5),posSets=[['PG'],['SG'],['SF'],['PF'],['C'],['PG','SG'],['SG','SF'],['SF','PF'],['PF','C']],positions=posSets[Math.floor(rng()*posSets.length)];const talent=clamp(82-i*.22+normal()*4,61,86),potential=clamp(Math.round(talent+8+rng()*8),72,97),o=Math.round(talent);const id=`fictional-${state.seasonYear}-prospect-${String(i+1).padStart(2,'0')}`;const name=prospectName(i);return {id,name,team:null,age,positions,position_group:positions.includes('C')?'big':positions.includes('PG')?'guard':'wing',roster_status:'draft_prospect',contract:{years:[],expiry:'RFA',qualifying_offer:null,cap_hold:null},headshot_url:null,stats_2025_26:null,ratings:{overall:o,skill_overall:o,impact:o,offense:clamp(o+Math.round(normal()*2),50,95),defense:clamp(o+Math.round(normal()*2),50,95),finishing:clamp(o+Math.round(normal()*4),45,95),three_pt:clamp(o+Math.round(normal()*6),40,95),free_throw:clamp(o+Math.round(normal()*5),45,95),shot_creation:clamp(o+Math.round(normal()*4),45,95),playmaking:clamp(o+(positions.includes('PG')?5:-1)+Math.round(normal()*3),45,95),ball_security:clamp(o+Math.round(normal()*3),45,95),offensive_rebounding:clamp(o+(positions.includes('C')?6:-3)+Math.round(normal()*3),40,95),defensive_rebounding:clamp(o+(positions.includes('C')?6:-1)+Math.round(normal()*3),40,95),stamina:clamp(o+4,50,96),perimeter_defense:clamp(o+(positions.includes('C')?-4:1)+Math.round(normal()*4),40,95),interior_defense:clamp(o+(positions.includes('C')?7:-3)+Math.round(normal()*4),40,95)},tendencies:null,rating_source:'fictional_prospect_model',data_confidence:.45,career_status:'fictional_rookie',data_quality:['fictional_future_prospect'],simulation_profile:null,development_profile:{career_stage:'development',trend:'rising_fast',prime_age_range:[25,29],baseline_next_year_overall_delta:2.0,note:'Fictional post-current-day prospect.'},rights_team:null,draft_projection:{current_overall:o,potential,scout_low:Math.max(o, potential-7-Math.floor(rng()*3)),scout_high:Math.min(99,potential+Math.floor(rng()*3)),rank:pickBand}}}
function generateDraftClass(){if(state.draft.generated)return;const classPlayers=[];for(let i=0;i<60;i++)classPlayers.push(makeProspect(i));state.generatedPlayers.push(...classPlayers);state.draft.generated=true;state.draft.prospectIds=classPlayers.map(p=>p.id);rebuildPlayerIndex();persist()}
function draftAvailable(){return (state.draft?.prospectIds||[]).map(id=>byId.get(id)).filter(p=>p&&currentStatus(p)==='draft_prospect').sort((a,b)=>(b.draft_projection.potential+b.ratings.overall*.65)-(a.draft_projection.potential+a.ratings.overall*.65))}
function currentDraftTeam(){return state.draft?.order?.[state.draft.pickIndex]||null}
function signDraftPick(p,teamAbbr,pick){state.assignments[p.id]=teamAbbr;state.statusOverrides[p.id]='active';p.roster_status='active';const salary=rookieSalaryForPick(pick);p.contract.years=Array.from({length:4},(_,i)=>({season_start:state.seasonYear,season:`${state.seasonYear+i}-${String((state.seasonYear+i+1)%100).padStart(2,'0')}`,amount:Math.round(salary*Math.pow(1.045,i)),option:i<2?'guaranteed':'team_option'}));p.contract.years.forEach((y,i)=>y.season_start=state.seasonYear+i);p.draft_projection={...(p.draft_projection||{}),rookieSeason:state.seasonYear};state.draft.selections.push({pick,team:teamAbbr,player_id:p.id});addTransaction('DRAFT',`${team(teamAbbr).abbr} selected ${p.name} with pick No. ${pick}.`,state.date);state.draft.pickIndex++}
function cpuDraftOne(){const pick=state.draft.pickIndex+1,tm=currentDraftTeam(),avail=draftAvailable();if(!tm||!avail.length)return;let best=[...avail].slice(0,8).sort((a,b)=>(b.draft_projection.potential+b.ratings.overall*.75+rng()*4)-(a.draft_projection.potential+a.ratings.overall*.75+rng()*4))[0];signDraftPick(best,tm,pick)}
function simToUserDraftPick(){while(state.draft.pickIndex<60&&currentDraftTeam()!==userTeam)cpuDraftOne();if(state.draft.pickIndex>=60)finishDraft();persist();renderView()}
function userDraftPlayer(id){if(currentDraftTeam()!==userTeam)return;const p=byId.get(id);if(!p||currentStatus(p)!=='draft_prospect')return;signDraftPick(p,userTeam,state.draft.pickIndex+1);simToUserDraftPick();toast(`${p.name.toUpperCase()} DRAFTED`)}
function autoPickUser(){if(currentDraftTeam()!==userTeam)return;const p=draftAvailable()[0];if(p)userDraftPlayer(p.id)}
function finishDraft(){state.pickHistory[state.seasonYear]=state.draft.order.slice(0,30);state.phase='free_agency';state.date=`${state.seasonYear}-07-01`;for(const p of players)if(currentStatus(p)==='draft_prospect'){state.statusOverrides[p.id]='free_agent'}persist();setTop()}
function draftHome(){if(!state.draft)return'';if(state.draft.pickIndex>=60){finishDraft();return freeAgencyHome()}if(currentDraftTeam()!==userTeam){while(state.draft.pickIndex<60&&currentDraftTeam()!==userTeam)cpuDraftOne();if(state.draft.pickIndex>=60){finishDraft();return freeAgencyHome()}persist()}const pick=state.draft.pickIndex+1,tm=currentDraftTeam(),avail=draftAvailable().slice(0,12),userPicks=state.draft.order.map((x,i)=>x===userTeam?i+1:null).filter(Boolean);return `${hero()}<div class="draftHero"><span>${state.seasonYear} NBA DRAFT · FICTIONAL FUTURE CLASS</span><h2>ON THE<br>BOARD.</h2><div class="draftPickNow">PICK ${pick} · ${team(tm)?.name||tm}</div></div><div class="notice good"><strong>Your picks:</strong> ${userPicks.join(' · ')}. Beginning with 2027, this save uses fictional prospects because the real historical/current-day pipeline has ended.</div><div class="sectionHead"><h2>Best Available</h2><span>${60-state.draft.pickIndex} PICKS LEFT</span></div><div class="prospectGrid">${avail.map((p,i)=>`<button class="prospect" data-draft="${p.id}"><div class="prospectFace">${img(p)}</div><div><span>#${i+1} BOARD</span><strong>${p.name}</strong><small>${p.positions.join('/')} · AGE ${p.age}</small></div><div class="prospectRating"><b>${p.ratings.overall}</b><span>OVR</span><em>${p.draft_projection.scout_low}–${p.draft_projection.scout_high} POT</em></div></button>`).join('')}</div><button class="primaryAction" id="autoPickUser">AUTO PICK BEST AVAILABLE</button><div class="sectionHead"><h2>Lottery Order</h2><span>3-2-1 LOTTERY</span></div><div class="draftOrder">${state.draft.order.slice(0,16).map((a,i)=>`<div class="draftOrderRow"><b>${i+1}</b>${logo(team(a))}<span>${team(a).name}</span></div>`).join('')}</div>`}
function freeAgencyHome(){const cut=Math.max(0,signedCount(userTeam)-15);return `${hero()}<div class="offHero"><span>${state.seasonYear} OFFSEASON</span><h2>FREE<br>AGENCY.</h2></div>${state.offseasonSummary?offseasonSummaryView():''}${cut?`<div class="notice danger"><strong>${cut} cuts required.</strong> Get to 15 before starting the season.</div>`:`<div class="notice good"><strong>Roster count: ${signedCount(userTeam)}/15.</strong> Sign, trade or cut players before opening night.</div>`}<div class="frontGrid"><button data-jump="market"><b>＋</b><span>FREE AGENTS</span></button><button data-jump="trade"><b>⇄</b><span>TRADE CENTER</span></button><button data-jump="roster"><b>◉</b><span>ROSTER</span></button></div><button class="primaryAction" id="startNextSeason" ${cut?'disabled':''}>START ${CAP.season} SEASON</button>`}
function offseasonSummaryView(){const s=state.offseasonSummary;if(!s)return'';const topUp=s.development.filter(x=>x.delta>0).slice(0,3),topDown=[...s.development].sort((a,b)=>a.delta-b.delta).filter(x=>x.delta<0).slice(0,3);return `<div class="sectionHead"><h2>League Evolution</h2><span>AGE + DEVELOPMENT</span></div>${s.retirements.length?`<div class="notice warn"><strong>Retirements:</strong> ${s.retirements.slice(0,8).map(x=>x.name).join(' · ')}${s.retirements.length>8?'…':''}</div>`:''}<div class="evolveGrid"><div><span>BIGGEST RISERS</span>${topUp.map(x=>`<b>${byId.get(x.id)?.name||x.id} +${x.delta}</b>`).join('')}</div><div><span>BIGGEST DECLINES</span>${topDown.map(x=>`<b>${byId.get(x.id)?.name||x.id} ${x.delta}</b>`).join('')}</div></div>`}
function startNextSeason(){if(signedCount(userTeam)>15)return;autoTrimCpu();autoFillCpu();state.seasonStarted=true;state.seasonComplete=false;state.phase='regular_season';state.date=DATES.opening_day;state.results={};state.seasonStats={};state.postseason=null;state.awards=null;state.draft=null;state.offseasonSummary=null;persist();renderView();setTop();toast(`${CAP.season} SEASON STARTED`)}

function addTransaction(type,text,date=state.date){state.transactions.push({id:'T'+Date.now()+Math.floor(rng()*1000),date,type,text})}
function waivePlayer(p,from,{cpu=false}={}){if(currentTeam(p)!==from)return false;state.assignments[p.id]=null;state.statusOverrides[p.id]='free_agent';state.deadCap[from]=(state.deadCap[from]||0)+salaryOf(p);addTransaction('WAIVED',`${team(from).abbr} waived ${p.name}.`);if(!cpu)toast(`${p.name.toUpperCase()} WAIVED`);return true}
function autoTrimCpu(){for(const t of teams){if(t.abbr===userTeam)continue;let roster=teamPlayers(t.abbr);while(roster.length>15){const cut=[...roster].sort((a,b)=>assetScore(a)-assetScore(b))[0];waivePlayer(cut,t.abbr,{cpu:true});roster=teamPlayers(t.abbr)}}persist()}
function autoFillCpu(){const fa=()=>freeAgents().sort((a,b)=>assetScore(b)-assetScore(a));for(const t of teams){if(t.abbr===userTeam)continue;while(signedCount(t.abbr)<14&&fa().length){const p=fa()[0];state.assignments[p.id]=t.abbr;state.statusOverrides[p.id]='active';state.salaryOverrides[p.id]=marketAsk(p);addTransaction('SIGNED',`${t.abbr} signed ${p.name}.`)}}}
function signPlayer(p){if(currentTeam(p)!=null||signedCount(userTeam)>=15)return;const rfa=p.roster_status==='restricted_free_agent_unsigned';if(rfa&&(p.rights_team||p.team)!==userTeam){toast('RFA OFFER SHEETS NOT IN v0.5');return}const amt=rfa?(p.contract?.qualifying_offer||marketAsk(p)):marketAsk(p);state.assignments[p.id]=userTeam;state.statusOverrides[p.id]='active';state.salaryOverrides[p.id]=amt;addTransaction('SIGNED',`${team(userTeam).abbr} signed ${p.name} to a one-year ${money(amt)} deal.`);persist();closeSheet();renderView();toast(`${p.name.toUpperCase()} SIGNED`)}
function maybeCpuTrade(d){if(!state.seasonStarted||d>DATES.trade_deadline||state.lastCpuTradeDate&&Math.abs((new Date(d)-new Date(state.lastCpuTradeDate))/86400000)<10||rng()>.025)return;const pool=teams.filter(t=>t.abbr!==userTeam&&signedCount(t.abbr)>=12);if(pool.length<2)return;const a=pool[Math.floor(rng()*pool.length)],others=pool.filter(x=>x.abbr!==a.abbr),b=others[Math.floor(rng()*others.length)];const ap=teamPlayers(a.abbr,{activeOnly:true}).filter(p=>overall(p)>=72&&overall(p)<=85),bp=teamPlayers(b.abbr,{activeOnly:true}).filter(p=>overall(p)>=72&&overall(p)<=85);if(!ap.length||!bp.length)return;const pa=ap[Math.floor(rng()*ap.length)],pb=bp.sort((x,y)=>Math.abs(assetScore(x)-assetScore(pa))-Math.abs(assetScore(y)-assetScore(pa)))[0];if(!pb||Math.abs(assetScore(pa)-assetScore(pb))>16)return;const sa=salaryOf(pa),sb=salaryOf(pb);if(!salaryMatchLegal(a.abbr,sa,sb)||!salaryMatchLegal(b.abbr,sb,sa))return;state.assignments[pa.id]=b.abbr;state.assignments[pb.id]=a.abbr;state.lastCpuTradeDate=d;addTransaction('TRADE',`${a.abbr} acquired ${pb.name} from ${b.abbr} for ${pa.name}.`,d)}

function bindPlayers(){document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>openPlayer(b.dataset.player))}
function bindDynamic(){document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{currentView=b.dataset.jump;renderView();scrollTo({top:0,behavior:'smooth'})});document.querySelectorAll('[data-ltab]').forEach(b=>b.onclick=()=>{leagueTab=b.dataset.ltab;renderView()});document.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>userDraftPlayer(b.dataset.draft));if($('#startSeason'))$('#startSeason').onclick=startSeason;if($('#startNextSeason'))$('#startNextSeason').onclick=startNextSeason;if($('#simDay'))$('#simDay').onclick=simNextDay;if($('#simNextGame'))$('#simNextGame').onclick=simToNextGame;if($('#simWeek'))$('#simWeek').onclick=simWeek;if($('#beginPostseason'))$('#beginPostseason').onclick=beginPostseason;if($('#simPlayIn'))$('#simPlayIn').onclick=simulatePlayIn;if($('#simRound'))$('#simRound').onclick=simulatePlayoffRound;if($('#beginOffseason'))$('#beginOffseason').onclick=beginOffseason;if($('#autoPickUser'))$('#autoPickUser').onclick=autoPickUser}
function renderView(){document.querySelectorAll('.navBtn').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));let html='';if(currentView==='home')html=homeView();else if(currentView==='roster')html=rosterView();else if(currentView==='league')html=leagueView();else if(currentView==='cap')html=capView();else if(currentView==='market')html=marketView();else if(currentView==='trade')html=tradeView();$('#view').innerHTML=html;bindPlayers();bindDynamic();if(currentView==='trade')bindTrade();setTop()}
function bindTrade(){document.querySelectorAll('[data-partner]').forEach(b=>b.onclick=()=>{tradePartner=b.dataset.partner;tradeTheirs.clear();tradeOffer=null;renderView()});document.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>{const set=b.dataset.side==='mine'?tradeMine:tradeTheirs;if(set.has(b.dataset.asset))set.delete(b.dataset.asset);else if(set.size<3)set.add(b.dataset.asset);tradeOffer=null;renderView()});if($('#proposeTrade'))$('#proposeTrade').onclick=proposeTrade}

function playerSeasonLine(p){const x=state.seasonStats[p.id];if(x?.gp)return {gp:x.gp,pts:(x.pts/x.gp).toFixed(1),reb:(x.reb/x.gp).toFixed(1),ast:(x.ast/x.gp).toFixed(1)};const s=p.stats_2025_26;return s?{gp:s.gp,pts:s.pts,reb:s.reb,ast:s.ast}:null}
function openPlayer(id){const p=byId.get(id);if(!p)return;const t=pteam(p),free=!t;if(t)setColors(t);else{document.documentElement.style.setProperty('--team','#5a2bd6');document.documentElement.style.setProperty('--team2','#ffb21c')}const s=playerSeasonLine(p),r=p.ratings,ct=currentTeam(p);const statHtml=s?`<div class="profileStats"><div class="profileStat"><b>${s.pts}</b><span>PTS</span></div><div class="profileStat"><b>${s.reb}</b><span>REB</span></div><div class="profileStat"><b>${s.ast}</b><span>AST</span></div><div class="profileStat"><b>${s.gp}</b><span>GP</span></div></div>`:`<div class="notice" style="margin-top:12px"><strong>No NBA sample yet.</strong> This player is running on a projection model.</div>`;const years=Object.prototype.hasOwnProperty.call(state.salaryOverrides,p.id)?`<div class="yearBox"><span>${CAP.season}</span><b>${money(state.salaryOverrides[p.id])}</b><em>SAVE CONTRACT</em></div>`:(p.contract?.years||[]).map(y=>`<div class="yearBox"><span>${y.season}</span><b>${money(y.amount)}</b><em>${pretty(y.option)}</em></div>`).join('');const keys=['finishing','three_pt','shot_creation','playmaking','ball_security','perimeter_defense','interior_defense','offensive_rebounding','defensive_rebounding','stamina','free_throw'];const ratings=r?`<div class="ratings">${keys.map(k=>`<div class="ratingLine"><span>${pretty(k)}</span><b>${r[k]}</b><div class="ratingBar"><i style="width:${r[k]}%"></i></div></div>`).join('')}</div>`:`<div class="notice">Projection ratings pending.</div>`;let action='';if(ct===userTeam)action=`<button class="dangerAction" id="waivePlayer">WAIVE / CUT PLAYER</button>`;else if(free&&currentStatus(p)!=='retired'&&currentStatus(p)!=='draft_prospect')action=`<button class="primaryAction" id="signPlayer" ${signedCount(userTeam)>=15?'disabled':''}>SIGN · ${money(marketAsk(p))}</button>`;$('#sheetInner').innerHTML=`<div class="sheetHero"><button class="close" id="closeSheet">×</button>${img(p,'bigPortrait')}<div class="sheetTitle"><h1>${p.name}</h1><p>${t?t.name:currentStatus(p)==='retired'?'RETIRED':'FREE AGENT'} · ${p.positions.join(' / ')} · AGE ${p.age} · ${role(p).toUpperCase()}</p></div></div><div class="sheetContent">${statHtml}<div class="profileStats"><div class="profileStat"><b>${overall(p)}</b><span>OVERALL</span></div><div class="profileStat"><b>${rating(p,'offense')}</b><span>OFFENSE</span></div><div class="profileStat"><b>${rating(p,'defense')}</b><span>DEFENSE</span></div><div class="profileStat"><b>${trend(p).includes('rising')?'↑':trend(p).includes('declin')?'↓':'→'}</b><span>${pretty(trend(p))}</span></div></div>${action}<section class="profileCard"><h3>Contract</h3><div class="yearScroll">${years||'<div class="notice">Contract detail pending.</div>'}</div></section><section class="profileCard"><h3>Ratings</h3>${ratings}</section><section class="profileCard"><h3>Career trajectory</h3><div class="notice"><strong>${pretty(p.development_profile?.career_stage||'unknown')}</strong> · Prime window ${p.development_profile?.prime_age_range?.join('–')||'—'} · next-year baseline ${p.development_profile?.baseline_next_year_overall_delta>0?'+':''}${p.development_profile?.baseline_next_year_overall_delta??'—'} OVR.</div></section>${p.draft_projection?`<section class="profileCard"><h3>Scouting</h3><div class="notice"><strong>Potential range ${p.draft_projection.scout_low}–${p.draft_projection.scout_high}</strong><br>True internal ceiling remains hidden from the GM view.</div></section>`:''}</div>`;$('#sheet').classList.add('open');document.body.style.overflow='hidden';$('#closeSheet').onclick=closeSheet;if($('#waivePlayer'))$('#waivePlayer').onclick=()=>{if(confirm(`Waive ${p.name}?`)){waivePlayer(p,userTeam);persist();closeSheet();renderView()}};if($('#signPlayer'))$('#signPlayer').onclick=()=>signPlayer(p)}
function closeSheet(){const t=team(userTeam);$('#sheet').classList.remove('open');document.body.style.overflow='';setColors(t)}
function toast(text){let el=document.getElementById('toast');if(!el){el=document.createElement('div');el.id='toast';el.className='toast';document.body.appendChild(el)}el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}

// Initialise.
document.querySelectorAll('.navBtn').forEach(b=>b.onclick=()=>{currentView=b.dataset.view;renderView();scrollTo({top:0,behavior:'smooth'})});
$('#sheet').addEventListener('click',e=>{if(e.target.id==='sheet')closeSheet()});
start();
})();
